import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;

public class Main {

    /** Counts how many times the underlying stream is asked for data. */
    static class Counting extends FilterInputStream {
        long calls = 0;
        long bytes = 0;
        Counting(InputStream in) { super(in); }
        @Override public int read() throws IOException {
            calls++;
            int v = super.read();
            if (v != -1) bytes++;
            return v;
        }
        @Override public int read(byte[] b, int off, int len) throws IOException {
            calls++;
            int n = super.read(b, off, len);
            if (n > 0) bytes += n;
            return n;
        }
    }

    public static void main(String[] args) throws Exception {
        Path p = Path.of("data.bin");
        byte[] payload = new byte[20000];
        for (int i = 0; i < payload.length; i++) payload[i] = (byte) ('A' + i % 26);
        Files.write(p, payload);

        Counting raw = new Counting(Files.newInputStream(p));
        long n1;
        try (InputStream in = raw) {
            n1 = 0;
            while (in.read() != -1) n1++;
        }
        System.out.println("byte-at-a-time, NO buffer : read() calls = " + raw.calls + " , bytes = " + raw.bytes);

        Counting buf = new Counting(Files.newInputStream(p));
        long n2;
        try (InputStream in = new BufferedInputStream(buf)) {
            n2 = 0;
            while (in.read() != -1) n2++;
        }
        System.out.println("byte-at-a-time, 4KB buffer: read() calls = " + buf.calls + " , bytes = " + buf.bytes);
        System.out.println("same byte count read      : " + (n1 == n2 && n1 == payload.length));
        System.out.println("underlying calls reduced  : " + (raw.calls > buf.calls * 10));
    }
}
